#---------------------------#
# DEBUG AREA 1
#---------------------------#
@token       = debug-area-1
@name        = DEBUG Area 1
@level       = 1
@size        = 22 x 30
@sheet       = mmrpg-overworld-2k25
#---------------------------#
@portals[]   = spawn(10-14)
#---------------------------#
@portals[]   = subspace-portal(18-26, debug-area-0__surface-portal)
#---------------------------#
@portals[]   = north-portal-1(10-12, debug-area-1__north-portal-2)
@portals[]   = north-portal-2(10-3, debug-area-1__north-portal-1)
@portals[]   = north-exit(10-1, debug-area-1n__south-exit, up-only)
#---------------------------#
@portals[]   = east-portal-1(12-14, debug-area-1__east-portal-2)
@portals[]   = east-portal-2(20-14, debug-area-1__east-portal-1)
@portals[]   = east-exit(22-14, debug-area-1e__west-exit, right-only)
#---------------------------#
@portals[]   = west-portal-1(8-14, debug-area-1__west-portal-2)
@portals[]   = west-portal-2(4-14, debug-area-1__west-portal-1)
@portals[]   = west-exit(1-14, debug-area-1w__east-exit, left-only)
#---------------------------#
@portals[]   = south-portal-1(10-16, debug-area-1__south-portal-2)
@portals[]   = south-portal-2(10-28, debug-area-1__south-portal-1)
@portals[]   = south-exit(10-30, debug-area-1s__north-exit, down-only)
#---------------------------#
# FIELD AND TERRAIN
#--------------------
@field       = gentle-countryside
@terrain[]   = grass(gentle-countryside)
@terrain[]   = subspace(prototype-subspace)
#---------------------------#
# ENCOUNTERS AND HABITATS
#--------------------------
@encounters  = met(2),trille-bot(1)
@habitats[]  = met(grass)
@habitats[]  = trille-bot(subspace)
#---------------------------#
# SPAWN AREA BUFFER
# + EVENT PANELS
# + GIFT ITEMS
#----------------------
@groups[]    = no-encounters_spawn-buffer(8-12...12-16)
@events[]    = auto-heal(8-12, healpad, any, trigger-effects, restore-team-energy, restore-team-weapons)
@events[]    = auto-reset(12-12, resetpad, any, trigger-effects, reset-team-attack, reset-team-defense, reset-team-speed)
@items[]     = first-consumable-eti(8-16, energy-tank, x1, always)
@items[]     = first-consumable-wti(12-16, weapon-tank, x1, always)
#---------------------------#
# LIGHT PLAYER PLATFORM
# + INIT ITEMS
#------------------------
@events[]     = light-platform-left(9-6, lightpad-left, any, drop-zone, item:light-program, activate-player-platform)
@events[]     = light-platform-middle(10-6, lightpad-middle, any, drop-zone, item:light-heart, activate-player-platform)
@events[]     = light-platform-right(11-6, lightpad-right, any, drop-zone, item:copy-core, activate-player-platform)
@items[]      = light-init-program(18-24, light-program, anchored)
@items[]      = light-init-heart(16-14, light-heart__1, anchored)
@items[]      = light-init-core(13-20, copy-core, anchored)
#---------------------------#
# INTRO ENCOUNTER
#------------------
@mechas[]    = light-runway-mecha(10-10, met, 1)
#---------------------------#
# MECHA PORTAL BOSSES
#----------------------
@mechas[]    = south-exit-mecha(10-30, octone, 1)
@mechas[]    = north-exit-mecha(10-1, frosty-throwman, 2)
@mechas[]    = west-exit-mecha(1-14, rockscotch, 3)
@mechas[]    = east-exit-mecha(22-14, antlin-g, 4)
#---------------------------#
# ITEMS CODES PICKUP
#---------------------
@items[]     = item-codes-pickup(2-22, item-codes)
#---------------------------#
# ITEM CORRIDOR PICKUPS
# + STARTER ABILITIES
#------------------------
@items[]      = energy-pellet-pickup(14-8, energy-pellet)
@items[]      = energy-capsule-pickup(14-6, energy-capsule)
@items[]      = weapon-pellet-pickup(15-8, weapon-pellet)
@items[]      = weapon-capsule-pickup(15-6, weapon-capsule)
@items[]      = attack-pellet-pickup(16-8, attack-pellet)
@items[]      = attack-capsule-pickup(16-6, attack-capsule)
@items[]      = defense-pellet-pickup(17-8, defense-pellet)
@items[]      = defense-capsule-pickup(17-6, defense-capsule)
@items[]      = speed-pellet-pickup(18-8, speed-pellet)
@items[]      = speed-capsule-pickup(18-6, speed-capsule)
#------------------------
@abilities[]  = light-buster-pickup(6-6, light-buster)
@abilities[]  = wily-buster-pickup(5-6, wily-buster)
@abilities[]  = cossack-buster-pickup(4-6, cossack-buster)
@abilities[]  = copy-shot-pickup(6-8, copy-shot)
@abilities[]  = copy-soul-pickup(5-8, copy-soul)
@abilities[]  = copy-style-pickup(4-8, copy-style)
#---------------------------#
# ISLAND BUTTON 1 + EVENTS
#-------------------------
@buttons[]   = island-button-1(16-12, green, up, set-group-terrain, island-paths-1, grass)
@groups[]    = island-paths-1(16-17...16-20, 15-20)
@mechas[]    = island-button-1-guard-1(15-12, met, 1)
@mechas[]    = island-button-1-guard-2(17-12, met, 1)
#---------------------------#
# ISLAND BUTTON 2 + EVENTS
#-------------------------
@buttons[]   = island-button-2(13-19, green, up, set-group-terrain, island-paths-2, grass)
@groups[]    = island-paths-2(9-20...11-20)
@mechas[]    = island-button-2-guard-1(12-19, met, 2)
@mechas[]    = island-button-2-guard-2(14-19, met, 2)
#---------------------------#
# ROLL RESCUE MISSION + EVENTS
#----------------------
@rescues[]   = rescue-roll-robot(6-21, roll, 2)
@mechas[]    = rescue-roll-guard-1(6-20, sniper-joe, 2)
@mechas[]    = rescue-roll-guard-2(7-21, sniper-joe, 2)
@items[]     = rescue-roll-pickup-1(8-19, extra-life)
#---------------------------#
# SUBSPACE BUTTON + EVENTS
#---------------------------
@bosses[]    = subspace-portal-boss(18-26, trill, 3, speed)
@items[]     = subspace-light-heart(18-27, light-heart__2)
@buttons[]   = subspace-button(18-28, purple, up, set-group-terrain, subspace-path, subspace)
@groups[]    = subspace-path(13-22...13-26, 14-26)
#---------------------------#
# NO ENCOUNTERS
#---------------------------
@groups[]    = no-encounters_temp(1-1...22-30)
